import Model from 'flarum/common/Model';
/** The `prediction-picks` type: one member's pick on a prediction (who picked what). */
export default class PickModel extends Model {
  optionId = Model.attribute('optionId');
  value = Model.attribute('value');
  hit = Model.attribute('hit');
  points = Model.attribute('points');
  user = Model.hasOne('user');
}
flarum.reg.add('ernestdefoe-predictions', 'forum/models/PickModel', PickModel);